argv:
$ErrorActionPreference='Stop'
$a = @(Get-NetAdapter | Where-Object { $_.Status -eq 'Up' -and $_.InterfaceDescription -match 'NCM' })
if ($a.Count -ne 1) { throw 'NCM interface not unique' }
$ip = @(Get-NetIPAddress -InterfaceIndex $a[0].ifIndex -AddressFamily IPv4 | Where-Object { $_.AddressState -eq 'Preferred' -and $_.IPAddress -like '169.254.*' })
if ($ip.Count -ne 1) { throw 'NCM IPv4 address not unique/preferred' }
[Console]::WriteLine(('NCM interface={0} source={1}' -f $a[0].ifIndex,$ip[0].IPAddress))
$c = New-Object System.Net.Sockets.TcpClient([System.Net.Sockets.AddressFamily]::InterNetwork)
try {
 $c.Client.Bind([System.Net.IPEndPoint]::new([System.Net.IPAddress]::Parse($ip[0].IPAddress),0))
 $c.Client.SetSocketOption([System.Net.Sockets.SocketOptionLevel]::IP,[System.Net.Sockets.SocketOptionName]31,[System.Net.IPAddress]::HostToNetworkOrder([int]$a[0].ifIndex))
 $x=$c.BeginConnect('169.254.42.1',22,$null,$null)
 if (-not $x.AsyncWaitHandle.WaitOne(5000)) { throw 'TCP connect timeout' }
 $c.EndConnect($x)
 [Console]::WriteLine(('LOCAL={0} REMOTE={1}' -f $c.Client.LocalEndPoint,$c.Client.RemoteEndPoint))
 $s=$c.GetStream(); $s.ReadTimeout=5000
 $b=New-Object byte[] 256; $n=$s.Read($b,0,$b.Length)
 [Console]::Write([Text.Encoding]::ASCII.GetString($b,0,$n))
} finally { $c.Close() }
